contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to call openMakeFor or openTakeFor; amount is UFixed18 encoded as uint256
    // kind = 0 => openMakeFor, kind = 1 => openTakeFor
    function run(uint8 kind, address account, uint256 amount) public payable {
        require(kind <= 1, "invalid kind");
        // record balances and relevant observable views
        uint256 beforeCBalance = address(c).balance;
        // latestVersion might be zero; both openMakeFor/openTakeFor require notClosed and various checks
        // We will call and record whether it reverts
        bool reverted;
        if (kind == 0) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterCBalance = address(c).balance;

        // General rule: the contract's balance cannot increase as a result of these calls
        // (position fees are charged via controller.collateral().settleAccount and not by transferring Ether into the product)
        // So assert that afterCBalance <= beforeCBalance when the call did not revert (if it reverted, state unchanged by call)
        assert(reverted || afterCBalance <= beforeCBalance);
    }

    receive() external payable {}
 }

