    // kind: 0 = openMakeFor, 1 = openTakeFor
    // amount: encoded UFixed18 as uint256
    function run(uint8 kind, address account, uint256 amount) public payable {
        require(kind <= 1, "invalid kind");

        uint256 beforeCBalance = address(c).balance;

        bool reverted;
        // Call must be a top-level statement. Use try/catch at top-level as allowed.
        if (kind == 0) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterCBalance = address(c).balance;

        // General rule: invoking openMakeFor/openTakeFor never increases the product's ETH balance.
        // If the call reverted, the state must be unchanged w.r.t. balance; if it succeeded, balance must be <= before.
        assert(reverted ? afterCBalance == beforeCBalance : afterCBalance <= beforeCBalance);
    }

    receive() external payable {}
}

