contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address account, uint256 amount, bool openMake) public payable {
        require(amount <= type(uint128).max, "amount too large");

        // read the latest version and the pre-position for the account before the mutating call
        uint256 beforeLatest = c.latestVersion();
        // read pre-position (public getter)
        (uint256 preOracleVersionBefore, , ) = c.pre(account);
        // also read the product-level pre to inspect same-version behavior
        (uint256 productPreVersion, , ) = c.pre();

        // perform the chosen action, catching reverts
        bool reverted;
        if (openMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount) ) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount) ) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After call, read the account's pre() and product pre() and latestVersion again
        (uint256 preOracleVersionAfter, , ) = c.pre(account);
        (uint256 productPreVersionAfter, , ) = c.pre();
        uint256 afterLatest = c.latestVersion();

        // General rule: if the call did not revert, then the account's pre().oracleVersion must be
        // set to the current latestVersion at call time (i.e., beforeLatest) or equal to product pre version,
        // and if it changed it should be non-decreasing; we assert a conservative invariant:
        // - If not reverted then preOracleVersionAfter >= preOracleVersionBefore and preOracleVersionAfter <= afterLatest
        // - If reverted then nothing is required (we allow no-change)
        assert(reverted || (preOracleVersionAfter >= preOracleVersionBefore && preOracleVersionAfter <= afterLatest));
    }

    // receive to accept ETH if needed
    receive() external payable {}
}

