        // pre(account) is a public getter returning (PrePosition memory)
        // Solidity returns structs via tuple of their members; PrePosition has (uint256 oracleVersion, Position openPosition, Position closePosition)
        (uint256 preOracleVersionBefore, , ) = c.pre(account);

        // Read product latestVersion() before call (used to compare later if needed)
        uint256 latestBefore = c.latestVersion();

        // Perform the chosen action, catching reverts
        bool reverted;
        if (openMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After call, read the account's pre().oracleVersion and product latestVersion
        (uint256 preOracleVersionAfter, , ) = c.pre(account);
        uint256 latestAfter = c.latestVersion();

        // General rule: if the call did not revert, the account's pre().oracleVersion must be non-decreasing
        // (>= previous) and must not exceed the product latestVersion() observed after the call.
        assert(reverted || (preOracleVersionAfter >= preOracleVersionBefore && preOracleVersionAfter <= latestAfter));
    }

    // receive to accept ETH if needed
    receive() external payable {}
}

