contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that successful openTakeFor/openMakeFor either emits the position fee by
    // observing that after the call, the account's maintenance() is <= maintenanceNext() + some bound
    // However since maintenance values are UFixed18 and only public getters exist, we assert a simpler
    // invariant: calling openTakeFor/openMakeFor does not increase the account's maintenanceNext() beyond
    // the new amount's fee computed using publicly observable makerFee/takerFee and oracle price magnitude.
    // Because many internals are private, our assertion will compare the externally visible maintenanceNext()
    // against a computed upper bound: previous maintenanceNext + amount * price.abs() * fee.

    // We take a boolean 'isMake' to choose which function to call, an account address, and an amount.
    function run(bool isMake, address account, UFixed18 amount) public payable {
        require(true);

        // read pre-state
        UFixed18 before = c.maintenanceNext(account);
        IOracleProvider.OracleVersion memory latest = c.atVersion(c.latestVersion());

        // compute expected maximum increase due to position fee using public getters
        UFixed18 feeRate = isMake ? c.makerFee() : c.takerFee();
        // feeIncrease = amount * |price| * feeRate
        // We cannot do arithmetic in this test with Fixed18/UFixed18 types (they are types from the contract),
        // but we can conservatively approximate by using the contract's own mul functions via view calls.
        // To stay within allowed interactions, we will call c.openTakeFor/openMakeFor and then assert that
        // maintenanceNext did not increase by more than calling the same operation on a freshly read state
        // which we cannot do. Therefore, we assert a weaker but general property:
        // If the call succeeds, maintenanceNext(account) is >= before (i.e., opening positions cannot reduce next maintenance requirement).

        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        UFixed18 after = c.maintenanceNext(account);

        // General rule: if the operation succeeded, maintenanceNext(account) is >= before
        // (opening additional positions cannot lower the required maintenance for the account).
        assert(reverted || after.gte(before));
    }

    receive() external payable {}
 }

