contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes an account and amount; tries to openMakeFor
    function run(address account, UFixed18 amount) public payable {
        require(account != address(0));
        // read pre-state via public getter
        (UFixed18 preMaker, ) = _readMakerTaker(account);

        bool reverted;
        try c.openMakeFor(account, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        (UFixed18 postMaker, ) = _readMakerTaker(account);

        // If the call did not revert, the maker position for the account must be >= preMaker
        // We express ">=" via !lt
        bool notDecreased = !postMaker.lt(preMaker);

        assert(reverted || notDecreased);
    }

    // helper to observe position(account).maker and .taker via public position() view
    function _readMakerTaker(address account) internal view returns (UFixed18 maker, UFixed18 taker) {
        (maker, taker) = c.position(account);
    }

    receive() external payable {}
}

