contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address account, uint256 amountRaw) public payable {
        require(account != address(0));
        // amountRaw is an arbitrary uint; interpret it as a UFixed18-like scaled value by using the public interfaces only.
        // We will call openTakeFor(account, amount) and then call settleAccount(account) and observe latestVersion(account).

        // read initial latest versions
        uint256 productLatestBefore = c.latestVersion();
        uint256 accountLatestBefore = c.latestVersion(account);

        // perform an openTakeFor that may revert; capture whether it reverted
        bool openedReverted;
        // create a UFixed18 value by calling a view that expects nothing; since UFixed18 is a type alias, we cannot construct it here.
        // Instead, we call openTakeFor with amount 0 when amountRaw == 0, otherwise with amount 1 (small non-zero) by invoking through try/catch.
        // This lets us avoid constructing the custom UFixed18 type directly; solidity will accept  UFixed18 as a param if literal 0 or 1 is used.
