        // - If the call reverted, we cannot guarantee state change, so we only assert that reverted == true implies feesAfter == feesBefore (no change occurred on revert observed through fees).
        // Combined into one assertion over observed values and revert flag.
        assert((!reverted && feesAfter <= feesBefore) || (reverted && feesAfter == feesBefore));
