        uint256 amountRaw = rawAmount % 1e18; // will be interpreted as units before wrapping

        // Build a UFixed18 value by calling UFixed18Lib.from via the public wrapper functions
        // We cannot construct UFixed18 directly here; instead we will pass a wrapped amount to c's functions
        // c expects UFixed18 type; Solidity ABI allows passing uint256 for that typedef.
        uint256 amount = amountRaw;

