        // We must call only through c's public surface. We get the controller address, then call its collateral().fees(account).
        // However controller() is public on c (inherited). We'll call through c.controller() which returns IController.
        IController controller = c.controller();
        ICollateral collateral = controller.collateral();

        // Read previous fee amount (UFixed18) by calling fees(account)
        // Note: UFixed18 is a typedef for uint256; the external ABI returns uint256.
        uint256 beforeFees = collateral.fees(account);

        // Attempt to perform the action, capturing whether it reverted.
        bool reverted;
        if (doOpenTake) {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read fees after attempting the action
        uint256 afterFees = collateral.fees(account);

        // General rule: fees for the account cannot decrease as a result of opening a position (fees only charged, never refunded here).
        // If the call reverted, state didn't change so afterFees == beforeFees. If it didn't revert, fees may have increased or stayed the same (if positionFee computed as zero).
        assert(reverted ? afterFees == beforeFees : afterFees >= beforeFees);
    }

