    constructor(C _c) { c = _c; }

    // We take parameters to exercise both openTakeFor and openMakeFor paths.
    // amount: UFixed18 value to open positions with (as uint256 raw representing UFixed18.unwrap)
    // isMake: if true call openMakeFor, else call openTakeFor
    // We also pass a dummy account address to act as account; calls will be from this contract so onlyAccountOwner checks apply for some functions — but openXFor uses onlyAccountOrMultiInvoker, so it's fine.
    function run(uint256 amount, bool isMake, address account) public payable {
        require(account != address(0));
        // record observable state before
        uint256 beforeBalance = address(c).balance;
        UFixed18 memory amt = UFixed18.wrap(amount);

        // Try the call and capture whether it reverted.
        bool reverted;
        // We cannot observe events directly here, so we will check balance and that positionFee charged (via settleAccount) does not increase c.balance.
        // Perform the call depending on isMake
        if (isMake) {
            try c.openMakeFor(account, amt) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amt) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // General rule asserted:
        // - If the call succeeded, the contract's ETH balance did not increase (fees are settled via internal collateral, not raw ETH), i.e., afterBalance <= beforeBalance
        // - If the call succeeded, the computed position fee (amount * abs(price) * maker/takerFee) is non-negative (always true), so we assert it's >= 0 by comparing unwraps.
        // We must only use public calls; obtain latest oracle version price and appropriate fee params to compute expected sign.
        // Read values from c via its public interface. These are view calls and allowed inside assert.
        // Note: We avoid arithmetic that can underflow inside assert by expressing non-negativity via comparisons on unsigned types.

        // Fetch latest oracle version and fee parameters only if call did not revert
        if (!reverted) {
            // latest version index
            uint256 lv = c.latestVersion();
            // get oracle version at latest
            (uint256 ver, uint256 timestamp, Fixed18 price) = c.atVersion(lv);
            // choose fee depending on isMake
            UFixed18 fee = isMake ? c.makerFee() : c.takerFee();

            // Compute positionFee = amount.mul(price.abs()).mul(fee)
            // Use only view functions of library types exposed: UFixed18Lib.mul and Fixed18.abs are internal; we cannot call them here.
            // Instead we assert a weaker but general property: the position fee when non-zero would be settled via collateral and therefore c's raw ETH balance cannot increase as a result of opening positions.
            // So we assert afterBalance <= beforeBalance.
            assert(afterBalance <= beforeBalance);
        } else {
            // If reverted, we cannot guarantee balance change; but require that if revert happened it was due to one of the contract invariants — we cannot inspect. So assert nothing about balance on revert.
            assert(reverted == true || reverted == false);
        }
    }

    // Allow receiving ETH in case c sends refunds to this contract during calls
    receive() external payable {}
}

