        // General rule: if the call succeeded, C's ETH balance did not increase.
        assert(reverted || afterBalance <= beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount is the raw uint256 ABI value used to construct a UFixed18 via UFixed18.wrap
    // isMake selects openMakeFor (true) or openTakeFor (false)
    function run(uint256 amount, bool isMake, address account) public payable {
        require(account != address(0));

        uint256 beforeBalance = address(c).balance;

        bool revertedMake;
        bool revertedTake;

        // Each state-changing call must be a top-level statement. We will attempt both calls separately
        // but only the selected one is relevant for the final assertion; the other is guarded by a require
        // so it is not executed.
        if (isMake) {
            // ensure we do not execute openTakeFor in this branch
            revertedTake = false;

            // try openMakeFor as a top-level statement
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                revertedMake = false;
            } catch {
                revertedMake = true;
            }
        } else {
            // ensure we do not execute openMakeFor in this branch
            revertedMake = false;

            // try openTakeFor as a top-level statement
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                revertedTake = false;
            } catch {
                revertedTake = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // General rule: if the attempted (selected) call succeeded, C's ETH balance did not increase.
        // Exactly one of revertedMake/revertedTake is meaningful depending on isMake.
        if (isMake) {
            assert(revertedMake || afterBalance <= beforeBalance);
        } else {
            assert(revertedTake || afterBalance <= beforeBalance);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
