    // single public test entry
    function run(address account, uint256 amount, bool openTake) public payable {
        require(amount > 0, "amount must be >0");

        // Observe latestVersion before
        uint256 beforeVersion = c.latestVersion();

        // We will call either openTakeFor or openMakeFor as msg.sender = this contract
        // These functions may revert; catch that and record
        bool reverted = false;
        // We also observe collateral side-effects by querying controller().collateral() fees via public API is not available directly,
        // but we can observe that latestVersion does not increase as consequence of these calls

        if (openTake) {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterVersion = c.latestVersion();

        // General rule asserted: these open*For calls (whether they reverted or not) do not advance the product latestVersion
        // Additionally, if the call succeeded (not reverted), the function must have emitted no change to latestVersion.
        // (We assert non-increase: afterVersion == beforeVersion)
        assert(afterVersion == beforeVersion || reverted == true);
    }

    // receive to accept ETH if needed (not used here)
    receive() external payable {}
}

