contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address account, uint256 amount, uint8 choice) public payable {
        // choice: 0=openTakeFor, 1=openMakeFor, 2=closeTakeFor, 3=closeMakeFor
        require(amount > 0, "amount>0");
        require(choice <= 3, "bad choice");

        // observe before latestVersion (view)
        uint256 beforeVersion = c.latestVersion();

        bool reverted;

        // perform exactly one top-level state-changing call on c and capture revert via try/catch
        if (choice == 0) {
            reverted = false;
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (choice == 1) {
            reverted = false;
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (choice == 2) {
            reverted = false;
            try c.closeTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = false;
            try c.closeMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe after latestVersion (view)
        uint256 afterVersion = c.latestVersion();

        // General rule: if the single modifying call succeeded (did not revert) then latestVersion must NOT have increased.
        // (If it increased, that must be because the call reverted.)
        assert(!(afterVersion > beforeVersion && reverted == false));
    }

    receive() external payable {}
}
